import itertools

# Build graph: cycle 0-1-2-...-13-0 plus chords i to i+3 mod 14
n = 14
edges = set()
for i in range(n):
    edges.add((i, (i+1) % n))
    edges.add((i, (i+3) % n))

# Ensure u < v
edges = [(min(u,v), max(u,v)) for (u,v) in edges]
edges = sorted(set(edges))
print("Number of edges:", len(edges))
print("Edges:", edges)

# Check vertex connectivity using brute force for small k
def is_connected(edges, n, removed_vertices):
    # BFS/DFS to check connectivity after removing vertices
    adj = {i: [] for i in range(n) if i not in removed_vertices}
    for u,v in edges:
        if u in removed_vertices or v in removed_vertices:
            continue
        adj[u].append(v)
        adj[v].append(u)
    if not adj:
        return True  # no vertices left
    start = next(iter(adj))
    visited = set()
    stack = [start]
    while stack:
        node = stack.pop()
        if node in visited:
            continue
        visited.add(node)
        for nb in adj[node]:
            if nb not in visited:
                stack.append(nb)
    return len(visited) == len(adj)

# Check vertex connectivity >= 3
connectivity = n
for k in range(1, 4):
    for removed in itertools.combinations(range(n), k):
        if not is_connected(edges, n, set(removed)):
            connectivity = k-1
            break
    if connectivity < k:
        break
else:
    connectivity = 3  # at least 3

print("Vertex connectivity:", connectivity)
